var ContentHashParser = class {
  async parse(content, context) {
    const encoder = new TextEncoder();
    const data = encoder.encode(content);
    const hashBuffer = await crypto.subtle.digest("SHA-256", data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
  }
};

// src/data/indexer/parser/LinksParser.ts
var LinksParser = class {
  parse(_content, context) {
    const links = context.metadata.links || [];
    const frontmatterLinks = context.metadata.frontmatterLinks || [];
    const regularLinks = links.map((link) => ({
      link: link.link,
      original: link.original,
      displayText: link.displayText || link.link,
      position: link.position,
      inFrontmatter: false
    }));
    const fmLinks = frontmatterLinks.map((link) => ({
      link: link.link,
      original: link.original,
      displayText: link.displayText || link.link,
      key: link.key,
      position: { start: { line: 0, col: 0, offset: 0 }, end: { line: 0, col: 0, offset: 0 } },
      inFrontmatter: true
    }));
    return [...regularLinks, ...fmLinks];
  }
};

