var SCHDULE_DATE_REGEX = /([⏳⌛]) *(\\d{4}-\\d{2}-\\d{2})/u;
var CANCELLED_DATE_REGEX = /❌ *(\\d{4}-\\d{2}-\\d{2})/u;

